// Original teaching material. CEFR labels describe the intended practice band,
// not a certified curriculum or a learner's measured proficiency.
function unit(id, level, title, subtitle, rule, tasks, writing) {
  const questions = tasks.map(([prompt, answer, sentence, translation, why, alternatives = [], mistakes = []]) => ({ prompt, answer, sentence, translation, why, alternatives, mistakes }));
  return { id, level, title, subtitle, rule, tasks: questions,
    examples: questions.slice(0, 2).map(q => `${q.sentence} → ${q.translation}`),
    writing: { prompt: writing[0], model: writing[1], checklist: writing[2] } };
}

